// The Yoyo Gyms logo for documents — PDFs and the ID card (CLAUDE.md §37).
//
// Embedded as base64, like the MuleSoo credit (mulesooCredit.js), so a PDF is
// stamped synchronously and offline: no fetch, no caller-signature changes.
// Generated from public/brand/yoyo-gyms-logo-on-*.png at 480×354.
//
// A gym's OWN logo, when it has set one in Settings, wins: see src/lib/pdf/brand.js.
// In shared/ because the platform's owner agreement PDF carries it too.

export const YOYO_LOGO_ASPECT = 480 / 354;

/** White + purple: on the ID card's near-black face. */
export const YOYO_LOGO_ON_DARK =
  'data:image/png;base64,';

/** Navy + purple: on white paper. */
export const YOYO_LOGO_ON_LIGHT =
  'data:image/png;base64,';
